import{_ as o,o as d,c as a,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"可口可乐（The Coca-Cola Company）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/可口可乐.md","filePath":"03_companies/可口可乐.md"}'),e={name:"03_companies/可口可乐.md"};function l(i,t,u,h,n,q){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="可口可乐-the-coca-cola-company" tabindex="-1">可口可乐（The Coca-Cola Company） <a class="header-anchor" href="#可口可乐-the-coca-cola-company" aria-label="Permalink to &quot;可口可乐（The Coca-Cola Company）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>The Coca-Cola Company</td></tr><tr><td>行业</td><td>饮料 / 消费食品</td></tr><tr><td>成立年份</td><td>1886年</td></tr><tr><td>总部</td><td>佐治亚州亚特兰大市</td></tr><tr><td>伯克希尔持股</td><td>约 9.3%（长期持有）</td></tr><tr><td>首次买入</td><td>1988年</td></tr><tr><td>完成建仓</td><td>1994年</td></tr><tr><td>总投资金额</td><td>约 13 亿美元</td></tr><tr><td>买入均价</td><td>约 3.25 美元/股（经拆股调整）</td></tr><tr><td>2022年股息收入</td><td>7.04 亿美元</td></tr><tr><td>最新市值（2022年底）</td><td>约 250 亿美元</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>可口可乐是全球最大的饮料公司，业务涵盖：</p><ul><li><strong>碳酸饮料</strong>：可口可乐、雪碧、芬达等全球性品牌</li><li><strong>瓶装水与果汁</strong>：Dasani、Minute Maid、Simply 等</li><li><strong>茶与咖啡</strong>：Georgia 咖啡、VitaCoCo 等区域品牌</li><li><strong>运动饮料</strong>：Powerade 与佳得乐竞争</li><li><strong>全球装瓶系统</strong>：通过特许经营装瓶商网络覆盖全球</li></ul><p>可口可乐在全球超过 200 个国家和地区开展业务，日均消耗超过 19 亿份饮料，是全球最具价值的品牌之一。截至1996年，年糖浆销量达到32亿加仑，对比1896年的仅11.6万加仑，增长超过2700倍。</p><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="巴菲特与可口可乐的渊源" tabindex="-1">巴菲特与可口可乐的渊源 <a class="header-anchor" href="#巴菲特与可口可乐的渊源" aria-label="Permalink to &quot;巴菲特与可口可乐的渊源&quot;">​</a></h3><p>巴菲特与可口可乐的缘分可以追溯到他童年时期：</p><ul><li><p><strong>1930年代</strong>：6岁的巴菲特就从祖父的杂货店花25美分买了一箱可口可乐，然后每瓶5美分零售出去，赚取一分钱利润。&quot;那时候我就发现可口可乐消费者吸引力太强，商业潜力太大，接下来五十二年我也看着可口可乐越来越好，就是一直没买，直到1988年夏天，我脑子终于眼睛对上脑子，买了一大块，真浪费了五十二年时间，但是我现在买了，我也开心。&quot; —— 1989年股东信</p></li><li><p><strong>1936年</strong>：26岁时巴菲特就已经买入过可口可乐股票。</p></li><li><p><strong>1958年</strong>：唐·基奥（后来成为可口可乐总裁）买下了巴菲特家街对面的房子，两人成为邻居和终生好友。这层关系也是巴菲特1988-1989年决定大手笔投资可口可乐的因素之一。</p></li></ul><h3 id="完整投资时间线" tabindex="-1">完整投资时间线 <a class="header-anchor" href="#完整投资时间线" aria-label="Permalink to &quot;完整投资时间线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间</th><th>事件</th><th>持股数量</th><th>持股比例</th><th>累计投资</th></tr></thead><tbody><tr><td>1988年</td><td>首次大规模买入</td><td>14,172,500股</td><td>-</td><td>约 6.3 亿美元</td></tr><tr><td>1989年</td><td>大幅增持</td><td>23,350,000股</td><td>-</td><td>约 10.2 亿美元</td></tr><tr><td>1990年</td><td>继续增持</td><td>46,700,000股</td><td>-</td><td>-</td></tr><tr><td>1992年</td><td>再次增持</td><td>93,400,000股</td><td>7.1%</td><td>-</td></tr><tr><td>1994年</td><td>完成最后增持</td><td><strong>200,000,000股</strong></td><td>7.8%</td><td><strong>累计 13 亿美元</strong></td></tr><tr><td>2003年</td><td>拆股后</td><td>400,000,000股</td><td>8.2%</td><td>-</td></tr><tr><td>2012年</td><td>股票回购提升</td><td>400,000,000股</td><td>8.9%</td><td>13 亿美元</td></tr><tr><td>2013年</td><td>股票回购提升</td><td>400,000,000股</td><td>9.1%</td><td>13 亿美元</td></tr><tr><td>2014年</td><td>股票回购提升</td><td>400,000,000股</td><td>9.2%</td><td>13 亿美元</td></tr><tr><td>2015年至今</td><td>股票回购提升</td><td><strong>400,000,000股</strong></td><td><strong>约 9.3%</strong></td><td>13 亿美元</td></tr></tbody></table><p><strong>关键特点</strong>：伯克希尔自1994年完成建仓后，<strong>近30年从未减持</strong>。持股数量一直保持4亿股不变，仅通过可口可乐自身的股票回购，持股比例从7.8%逐步提升至约9.3%。</p><h3 id="_1988年的历史性买入" tabindex="-1">1988年的历史性买入 <a class="header-anchor" href="#_1988年的历史性买入" aria-label="Permalink to &quot;1988年的历史性买入&quot;">​</a></h3><p>1988年，巴菲特开始大量买入可口可乐股票，这是伯克希尔历史上最重要的投资决策之一。</p><p><strong>投资背景：</strong></p><ul><li>1987年10月股灾之后，股市大幅下跌</li><li>可口可乐股价也从高点回落</li><li>罗伯托·戈伊苏埃塔领导下的可口可乐已经重新聚焦核心业务，进入高速增长期</li><li>巴菲特发现可口可乐在海外市场仍有巨大增长空间</li></ul><p><strong>投资规模：</strong></p><ul><li>总投资约 <strong>13 亿美元</strong></li><li>占伯克希尔当时股票投资组合的约 35%</li><li>买入均价约 3.25 美元/股（拆股调整后）</li></ul><h3 id="战略眼光" tabindex="-1">战略眼光 <a class="header-anchor" href="#战略眼光" aria-label="Permalink to &quot;战略眼光&quot;">​</a></h3><p>巴菲特买入可口可乐的核心理由与其投资哲学高度一致：</p><ol><li><strong>品牌护城河</strong>：可口可乐是全球最强的消费品牌之一</li><li><strong>定价权</strong>：消费者愿意为可口可乐品牌支付溢价</li><li><strong>全球化潜力</strong>：当时海外市场仍有巨大增长空间</li><li><strong>管理层</strong>：<a href="/04_people/罗伯托·戈伊苏埃塔">罗伯托·戈伊苏埃塔</a>（Roberto Goizueta）和唐·基奥是卓越的管理者搭档</li></ol><blockquote><p>&quot;我五六岁就喝可口可乐，1936年我就买可口可乐股票，五分钱两杯，我买过来零售五分钱一杯卖，赚一分钱，那时候我就发现可口可乐消费者吸引力太强，商业潜力太大，接下来五十二年我也看着可口可乐越来越好，就是一直没买，直到1988年夏天，我脑子终于眼睛对上脑子，买了一大块，真浪费了五十二年时间，但是我现在买了，我也开心，现在可口可乐海外销量爆发，CEO Roberto Goizueta重新聚焦公司，把公司政策重新思考，行动起来，原来可口可乐已经世界无处不在，现在还在加速增长，真伟大。&quot; —— 1989年股东信</p></blockquote><blockquote><p>&quot;营销财务能力结合得这么好，Roberto把公司做到股东价值最大化，真的是股东梦想，我们很幸运能买到。&quot; —— 1989年股东信</p></blockquote><h3 id="长期持有与回报" tabindex="-1">长期持有与回报 <a class="header-anchor" href="#长期持有与回报" aria-label="Permalink to &quot;长期持有与回报&quot;">​</a></h3><p>巴菲特对可口可乐的持有超过三十五年：</p><table tabindex="0"><thead><tr><th>时期</th><th>表现</th></tr></thead><tbody><tr><td>1988-1998</td><td>股价增长约 10 倍</td></tr><tr><td>1998 年峰值</td><td>可口可乐成为伯克希尔最大持仓</td></tr><tr><td>1998-2010</td><td>股价长期盘整，但巴菲特从未减持</td></tr><tr><td>2010至今</td><td>持续分红增长，市值稳步回升</td></tr><tr><td>持有至今</td><td>依然是伯克希尔的核心标志性持仓</td></tr></tbody></table><p><strong>分红增长奇迹：</strong></p><ul><li>1995年（首次完整分红年）：伯克希尔获得 <strong>8800万美元</strong> 股息</li><li>2011年：股息增长至 <strong>3.76亿美元</strong></li><li>2022年：股息已增长至 <strong>7.04亿美元</strong></li><li>28年间股息增长 <strong>8倍</strong>，年均复利增长约 <strong>8%</strong></li></ul><p>&quot;可口可乐在1995年向我们支付了8800万美元，即我们完成购买股票的次年。此后每年，可口可乐都增加了股息。2011年，我们几乎肯定会从可口可乐收到3.76亿美元，比去年增加2400万美元。在十年内，我预计这3.76亿美元将翻倍。到那个时期结束时，我不会惊讶于我们享有的可口可乐年度收益超过我们为该投资支付金额的100%。时间是伟大企业的朋友。&quot; —— 2010年股东信</p><p>&quot;1994年8月——是的，1994年——伯克希尔完成了为期七年的购买，收购了我们现在持有的4亿股可口可乐。总成本为13亿美元——在当时对伯克希尔来说是一笔相当可观的金额。1994年我们从可口可乐收到的现金股息为7500万美元。到2022年，股息已增长至7.04亿美元。每年都有增长，如同生日一样确定无误。查理和我需要做的只是兑现可口可乐的季度股息支票。我们预计这些支票很可能继续增长。&quot; —— 2022年股东信</p><p>从13亿美元的初始投资，到2022年底市值达到250亿美元，加上累计获得超过100亿美元的股息分红，这笔投资的总回报超过25倍，年化回报率约为<strong>11%</strong>（28年），完美印证了伟大企业复利增长的力量。</p><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-全球最强消费品牌" tabindex="-1">1. 全球最强消费品牌 <a class="header-anchor" href="#_1-全球最强消费品牌" aria-label="Permalink to &quot;1. 全球最强消费品牌&quot;">​</a></h3><ul><li>BrandZ 全球品牌价值排行榜前三常客</li><li>消费者对品牌的认知跨越文化与国界</li><li>&quot;可乐&quot;几乎成为碳酸饮料的代名词</li><li>全球任何角落都能找到可口可乐产品，这种无处不在的分销网络本身就是巨大的护城河</li></ul><h3 id="_2-全球化装瓶特许经营体系" tabindex="-1">2. 全球化装瓶特许经营体系 <a class="header-anchor" href="#_2-全球化装瓶特许经营体系" aria-label="Permalink to &quot;2. 全球化装瓶特许经营体系&quot;">​</a></h3><ul><li>轻资产运营模式：品牌与灌装分离</li><li>特许经营商负责本地化运营</li><li>资本效率高，回报率高</li></ul><h3 id="_3-持续定价能力" tabindex="-1">3. 持续定价能力 <a class="header-anchor" href="#_3-持续定价能力" aria-label="Permalink to &quot;3. 持续定价能力&quot;">​</a></h3><ul><li>产品价格可随通胀上调</li><li>消费者对小幅涨价不敏感</li><li>带来稳定的利润率提升</li></ul><h3 id="_4-不可复制的规模效应" tabindex="-1">4. 不可复制的规模效应 <a class="header-anchor" href="#_4-不可复制的规模效应" aria-label="Permalink to &quot;4. 不可复制的规模效应&quot;">​</a></h3><blockquote><p>&quot;如果每天醒来有 10 亿人在等待你提供的产品，你就能非常富有。&quot; —— 1996年</p></blockquote><p>&quot;像可口可乐和吉列这样的公司很可能会被贴上&quot;必然&quot;的标签。预测者可能对这两家公司十年或二十年后到底会做多少软饮料或剃须刀业务的具体预测略有分歧。我们谈论&quot;必然性&quot;并不是要淡化这些公司必须继续进行的重要工作，比如制造、分销、包装和产品创新等领域。然而，最终，任何明智的观察者——甚至这些公司最激烈的竞争对手（假设他们在诚实地评估这件事）——都不会质疑可口可乐和吉列将在一个投资人的生命周期内主导各自的全球领域。事实上，它们的主导地位可能会加强。在过去十年中，这两家公司都显著扩大了本已巨大的市场份额，所有迹象都表明它们将在下一个十年重复这一表现。&quot; —— 1996年股东信</p><p>&quot;真正伟大的企业必须有持久的&quot;护城河&quot;，保护投入资本获得高额回报。资本主义动力学保证，竞争对手会不断攻击任何赚取高回报的企业&quot;城堡&quot;。因此，强大的壁垒，比如成为低成本生产商（<a href="/03_companies/GEICO">GEICO</a>，好市多），或者拥有全球强大品牌（可口可乐，<a href="/03_companies/吉列">吉列</a>, <a href="/03_companies/美国运通">美国运通</a>），对持续成功至关重要。商业史充满了&quot;罗马烟花&quot;式企业，护城河后来证明是虚幻的，很快就被跨越了。&quot; —— 2007年股东信</p><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;我早就应该买，反应慢无所谓，反正现在买了，我们很高兴。&quot; —— 1989年</p></blockquote><blockquote><p>&quot;短期来看，市场是一台投票机——反映的是只需要资金、不需要智慧或情绪稳定的选民登记测试——但长期来看，市场是一台称重机。&quot; —— 1993年（引用<a href="/04_people/本·格雷厄姆">本·格雷厄姆</a>）</p></blockquote><blockquote><p>&quot;很难找到一家与可口可乐规模相当的公司，销售像可口可乐这样不变的产品，能够指出像可口可乐这样的十年记录。在随后的55年里，可口可乐的产品线略有扩大，但值得注意的是，这一描述仍然非常贴切。&quot; —— 1993年</p></blockquote><blockquote><p>&quot;如果你在 1988 年买入可口可乐并持有到今天，你的回报是惊人的。问题是，你能不能在那时候就看到这一点？&quot; —— 1996年</p></blockquote><blockquote><p>&quot;吉列和可口可乐都是伟大的企业，它们的共同点是有巨大的定价权。&quot; —— 1996年</p></blockquote><blockquote><p>&quot;罗伯特·伍德鲁夫——用数十年时间打造可口可乐的商业天才，持有该公司大量股份——曾被问及什么时候可能是卖出可口可乐股票的好时机。伍德鲁夫有一个简单的回答：&quot;我不知道。我从来没有卖过。&quot; —— 1996年</p></blockquote><blockquote><p>&quot;1896年，可口可乐虽然已经是领先的软饮料，但仅仅存在了十年。然而，它未来100年的蓝图已经画好了。公司总裁阿萨·坎德勒在报告14.8万美元销售额时说：&quot;我们在努力走向全世界方面从不懈怠，教导人们可口可乐是增进所有人健康和良好感觉的绝佳产品。&quot;虽然&quot;健康&quot;可能有些夸大，但我喜欢可口可乐在一个世纪后的今天仍然依赖坎德勒的基本主题。坎德勒继续说道，就像罗伯托现在可以说的那样：&quot;从未有同类产品如此牢固地扎根于公众的喜爱之中。&quot;顺便说一下，那年的糖浆销量为116,492加仑，而1996年约为32亿加仑。&quot; —— 1996年</p></blockquote><blockquote><p>罗伯托·戈伊苏埃塔&quot;发给我的一份手写便条的摘录说明了他的心态：&quot;顺便说一句，我告诉奥尔吉塔，她所谓的痴迷，你称之为专注。我更喜欢你的术语。&quot;像所有认识罗伯托的人一样，我会非常想念他。与他对公司的关心一致，罗伯托在很久以前——远在看起来必要之前——就为无缝继任做准备。罗伯托知道道格·伊维斯特是接管的合适人选，多年来与道格合作，确保变革时刻到来时不会失去动力。可口可乐公司在道格领导下将与在罗伯托领导下一样是一辆蒸汽压路机。&quot; —— 1997年</p></blockquote><blockquote><p>&quot;无论一个世纪后的货币是基于黄金、贝壳、鲨鱼牙齿还是一张纸（就像今天一样），人们愿意用他们日常劳动的几分钟来交换一杯可口可乐或一些<a href="/03_companies/喜诗糖果">喜诗糖果</a>花生脆糖。在未来，美国人口将比现在移动更多商品、消费更多食物、需要更多居住空间。人们将永远交换他们生产的与他人生产的。&quot; —— 2011年</p></blockquote><blockquote><p>&quot;美国运通于1850年开始运营，可口可乐于1886年在亚特兰大一家药店推出。（伯克希尔哈撒韦对新手不太感兴趣。）多年来，两家公司都尝试向不相关领域扩张，但都发现这些尝试收效微。在过去——但绝对不是现在——两家公司甚至都被管理不善。但每家在其核心业务上都取得了巨大成功，并随着条件的变化不时重塑。至关重要的是，他们的产品&quot;走向世界&quot;。可口可乐和美国运通都成为了全球认可的品牌名称，就像他们的核心产品一样，液体消费和无争议的金融信任是我们世界永恒的必需品。&quot; —— 2023年</p></blockquote><blockquote><p>&quot;2023年，我们没有买卖美国运通或可口可乐的任何股票——延续了我们自己的&quot;长睡者&quot;——这种沉睡已经持续了二十多年。去年，两家公司都通过增加收益和股息来奖励我们的不作为。事实上，我们2023年获得的美国运通收益份额大大超过了我们很久以前购买时花费的13亿美元。...我能创造出比这两家公司更好的全球业务吗？正如伯蒂会告诉你的：&quot;不可能。&quot; —— 2023年</p></blockquote><blockquote><p>&quot;当你发现一家真正出色的企业时，坚持持有它。耐心是有回报的，一家有出色的企业可以抵消许多不可避免的平庸决策。&quot; —— 2023年</p></blockquote><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>营收</th><th>净利润</th><th>备注</th></tr></thead><tbody><tr><td>1938</td><td>约 0.76亿美元</td><td>-</td><td>销售2.07亿箱</td></tr><tr><td>1988（投资年）</td><td>83亿美元</td><td>8亿美元</td><td>巴菲特开始买入</td></tr><tr><td>1993</td><td>-</td><td>-</td><td>销售107亿箱，较1938年增长50倍</td></tr><tr><td>1996</td><td>-</td><td>-</td><td>糖浆销量32亿加仑</td></tr><tr><td>1998（高峰期）</td><td>185亿美元</td><td>35亿美元</td><td>股价创历史新高</td></tr><tr><td>2004</td><td>约 217亿美元</td><td>约 48亿美元</td><td>经历减值冲销后</td></tr><tr><td>2022</td><td>约 430亿美元</td><td>约 78亿美元</td><td>持续增长</td></tr><tr><td>2023</td><td>458亿美元</td><td>97亿美元</td><td>持续增长</td></tr></tbody></table><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><ul><li><a href="/04_people/罗伯托·戈伊苏埃塔">罗伯托·戈伊苏埃塔</a>（Roberto Goizueta）—— 1981-1997年担任 CEO，卓越的经营者，在他任内将可口可乐市值从44亿美元提升到580亿美元</li><li>唐·基奥（Don Keough）—— 总裁，戈伊苏埃塔的完美搭档，巴菲特的奥马哈邻居和好友，在&quot;新可口可乐&quot;事件中力挽狂澜</li><li>道格·伊维斯特（Doug Daft）—— 1997-2004年担任 CEO，继任后保持了公司增长</li><li>阿萨·坎德勒（Asa Griggs Candler）—— 可口可乐早期灵魂人物，奠定了公司全球化基础</li><li>罗伯特·伍德鲁夫（Robert W. Woodruff）—— 长期领导者，将可口可乐打造成全球品牌</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1962, 1967, 1968, 1983, 1985, 1988, 1989, 1990, 1991, 1992, 1993, 1994, 1995, 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2009, 2010, 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024, 2025</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦">伯克希尔哈撒韦</a> - 投资主体</li><li><a href="/03_companies/喜诗糖果">喜诗糖果</a> - 同期经典收购案例</li><li><a href="/03_companies/美国运通">美国运通</a> - 同期重要持仓</li><li><a href="/03_companies/富国银行">富国银行</a> - 同期重要持仓</li><li><a href="/04_people/罗伯托·戈伊苏埃塔">罗伯托·戈伊苏埃塔</a> - 核心人物</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1988年/翻译">/01_letters/1988年/翻译</a></li><li><a href="/01_letters/1996年/翻译">/01_letters/1996年/翻译</a></li><li><a href="/01_letters/2012年/翻译">/01_letters/2012年/翻译</a></li><li><a href="/01_letters/2024年/翻译">/01_letters/2024年/翻译</a></li></ul><hr><p><em>最后更新：2026-04-16</em></p>',70)])])}const c=o(e,[["render",l]]);export{p as __pageData,c as default};
